python3 << 'EOF'
import fitz
d = fitz.open('eprint/limit-stat.pdf')
print(len(d))
p = d[0]
print(p.rect)
txt = []
for b in p.get_text('dict')['blocks']:
    for l in b.get('lines', []):
        for s in l['spans']:
            txt.append((round(s['origin'][0],1), round(s['origin'][1],1), s['text']))
for t in txt: print(t)
EOF
